function captureNavigationState(){const searches={},page={},sort={},filters={},checkboxes={};document.querySelectorAll('.grid-search[data-grid]').forEach(input=>searches[input.dataset.grid]=input.value);document.querySelectorAll('.grid-pagination span[id$="_page"]').forEach(label=>{const match=label.textContent.match(/Page (\d+)/);if(match)page[label.id.replace(/_page$/,'')]=Number(match[1]);});document.querySelectorAll('.erp-data-grid[data-grid]').forEach(grid=>{const id=grid.dataset.grid,table=document.getElementById(id),meta=document.getElementById(id+'_meta');sort[id]={key:table?.dataset.sortKey||'',dir:table?.dataset.sortDir||''};checkboxes[id]=[...grid.querySelectorAll('tr[data-row] .grid-row:checked')].map(input=>Number(input.closest('tr').dataset.row));try{filters[id]=JSON.parse(meta?.textContent||'{}').filters||{};}catch{filters[id]={};}});return{searches,page,sort,filters,checkboxes,activeTabs:[...document.querySelectorAll('.tab.active[data-tab]')].map(tab=>tab.dataset.tab),scrollY:window.scrollY};}
