const moduleNavDefaults={AP:['/ap','/ap/incoming-documents','/ap/bills','/ap/payments','/ap/vendors','/ap/bill-approvals','/ap/approvals','/ap/approval-thresholds','/ap/release','/ap/bills-pending-payment','/ap/aging','/ap/cash-requirements'],AR:['/ar','/ar/invoices','/ar/payments','/ar/customers','/ar/processes/release','/ar/reports/aging','/ar/reports/sales-tax','/ar/reports/tax-liability','/ar/reports/tax-collected','/ar/tax','/ar/tax-zones','/ar/tax-categories','/ar/customer-exemptions'],Finance:['/finance','/finance/journal','/finance/chart-of-accounts','/finance/financial-periods','/finance/year-end-close','/finance/trial-balance','/finance/reclassify','/finance/email-settings'], 'Purchase Orders':['/purchase-orders','/purchase-orders/orders','/purchase-orders/receipts','/purchase-orders/process','/purchase-orders/open-lines','/purchase-orders/unbilled-receipts','/purchase-orders/reports/open']};
const navPrefKey=(m)=>`nav_pref_${m}`;
const OBSOLETE_FINANCE_NAV=new Set(['/finance/branches','/finance/journal-inquiry','/finance/processes/reverse-journals']);
const getNavPrefs=(m,all)=>{const defaults=moduleNavDefaults[m]||all.map(a=>a.route); let stored=null; try{stored=JSON.parse(localStorage.getItem(navPrefKey(m))||'null');}catch{stored=null;} if(Array.isArray(stored)&&m==='Finance'){const cleaned=stored.filter(p=>!OBSOLETE_FINANCE_NAV.has(p?.route));if(cleaned.length!==stored.length){localStorage.setItem(navPrefKey(m),JSON.stringify(cleaned));stored=cleaned;}} if(!Array.isArray(stored)) return all.map((x,i)=>({route:x.route,label:x.label,section:x.section,visible:defaults.includes(x.route),order:i,pinned:false})); const allowed=new Set(all.map(x=>x.route)); const by=new Map(stored.filter(p=>allowed.has(p?.route)).map(p=>[p.route,p])); all.forEach((x,i)=>{if(!by.has(x.route)&&defaults.includes(x.route)) by.set(x.route,{route:x.route,label:x.label,section:x.section,visible:true,order:i,pinned:false});}); return [...by.values()].map(p=>({...p,label:(all.find(x=>x.route===p.route)?.label)||p.label,section:(all.find(x=>x.route===p.route)?.section)||p.section}));};
const saveNavPrefs=(m,p)=>localStorage.setItem(navPrefKey(m),JSON.stringify(p));
function customizeNav(moduleName,allItems){
  const by=Object.fromEntries(allItems.map(i=>[i.route,i]));
  let prefs=getNavPrefs(moduleName,allItems).sort((a,b)=>a.order-b.order);
  const overlay=document.createElement('div'); overlay.className='cn-overlay';
  overlay.innerHTML=`<div class='cn-modal'><div class='cn-head'><h3>Customize Navigation</h3><p>Choose which functions appear in your left navigation.</p></div><div class='cn-filters'><input id='cnSearch' placeholder='Search functions'><select id='cnModule'><option>${moduleName}</option></select><select id='cnSection'><option value=''>All Sections</option>${[...new Set(allItems.map(i=>i.section))].map(x=>`<option>${x}</option>`).join('')}</select></div><div id='cnList' class='cn-list'></div><div class='cn-foot'><button id='cnSave'>Save Changes</button><button id='cnReset'>Reset to Default</button><button id='cnCancel'>Cancel</button></div></div>`;
  document.body.appendChild(overlay);
  const render=()=>{const q=(overlay.querySelector('#cnSearch').value||'').toLowerCase(); const sec=overlay.querySelector('#cnSection').value; const rows=prefs.filter(p=>by[p.route]&&(!q||p.label.toLowerCase().includes(q))&&(!sec||by[p.route].section===sec)); overlay.querySelector('#cnList').innerHTML=rows.map((p,i)=>`<div class='cn-row' draggable='true' data-r='${p.route}'><span class='cn-drag'>☰</span><span class='cn-name'>${p.label}</span><span class='cn-badge'>${by[p.route].section}</span><label class='cn-switch'><input type='checkbox' class='cn-vis' data-r='${p.route}' ${p.visible?'checked':''}><span></span></label><button class='cn-star ${p.pinned?'on':''}' data-r='${p.route}'>★</button></div>`).join('');
    let drag=''; overlay.querySelectorAll('.cn-row').forEach(r=>{r.ondragstart=()=>drag=r.dataset.r; r.ondragover=e=>e.preventDefault(); r.ondrop=()=>{const to=r.dataset.r; const a=prefs.findIndex(x=>x.route===drag), b=prefs.findIndex(x=>x.route===to); if(a<0||b<0)return; prefs.splice(b,0,prefs.splice(a,1)[0]); prefs.forEach((x,ix)=>x.order=ix); render();};});
    overlay.querySelectorAll('.cn-vis').forEach(c=>c.onchange=()=>{const p=prefs.find(x=>x.route===c.dataset.r); if(p) p.visible=c.checked;});
    overlay.querySelectorAll('.cn-star').forEach(b=>b.onclick=()=>{const p=prefs.find(x=>x.route===b.dataset.r); if(p){p.pinned=!p.pinned; b.classList.toggle('on',p.pinned);} });
  };
  render();
  overlay.querySelector('#cnSearch').oninput=render; overlay.querySelector('#cnSection').onchange=render;
  overlay.querySelector('#cnCancel').onclick=()=>overlay.remove();
  overlay.querySelector('#cnSave').onclick=()=>{saveNavPrefs(moduleName,prefs); overlay.remove(); router();};
  overlay.querySelector('#cnReset').onclick=()=>{if(!confirm('Are you sure you want to reset navigation to the default layout?')) return; localStorage.removeItem(navPrefKey(moduleName)); overlay.remove(); router();};
}


const lookupFilter=(inputId,_listId,items,onPick)=>{const inp=$(inputId); if(!inp) return; inp.classList.add('search-input'); const wrap=document.createElement('div'); wrap.className='erp-lookup-panel hidden'; const list=document.createElement('div'); list.className='erp-lookup-list'; wrap.appendChild(list); document.body.appendChild(wrap); let active=-1, rows=[]; const place=()=>{const r=inp.getBoundingClientRect(); wrap.style.left=r.left+'px'; wrap.style.top=(r.bottom+2)+'px'; wrap.style.width=Math.max(r.width,360)+'px';}; const close=()=>{wrap.classList.add('hidden'); active=-1;}; const fmt=(m)=>`${m.id}    ${m.name}`; const pick=(m)=>{inp.value=fmt(m); onPick&&onPick(m); close();}; const matches=(m,q)=>{const t=String(q||'').trim().toLowerCase(); const fields=[m.id,m.name,m.legalName,m.email,...(Array.isArray(m.aliases)?m.aliases:[])].map(value=>String(value||'').toLowerCase()); return !t||fields.some(value=>value.includes(t));}; const render=(q='')=>{const filtered=items.filter(m=>matches(m,q)).slice(0,60); if(!filtered.length){list.innerHTML="<div class='erp-lookup-empty'>No matches</div>"; rows=[]; active=-1; wrap.classList.remove('hidden'); place(); return;} list.innerHTML=filtered.map((m,i)=>`<button type='button' class='erp-lookup-row ${i===active?'active':''}' data-i='${i}'><span class='erp-lookup-id'>${m.id}</span><span class='erp-lookup-name'>${m.name}</span></button>`).join(''); rows=[...list.querySelectorAll('.erp-lookup-row')]; rows.forEach((r,i)=>{r.onpointerdown=e=>e.preventDefault();r.onclick=e=>{e.preventDefault();e.stopPropagation();pick(filtered[i]);};}); wrap.classList.remove('hidden'); place();}; inp.addEventListener('focus',()=>render(items.some(m=>fmt(m)===inp.value)?'':inp.value)); inp.addEventListener('input',()=>{active=-1;render(inp.value);}); inp.addEventListener('keydown',(e)=>{if(e.key==='ArrowDown'){e.preventDefault(); if(wrap.classList.contains('hidden')) render(inp.value); active=Math.min(active+1,rows.length-1); rows.forEach((r,i)=>r.classList.toggle('active',i===active));} if(e.key==='ArrowUp'){e.preventDefault(); active=Math.max(active-1,0); rows.forEach((r,i)=>r.classList.toggle('active',i===active));} if(e.key==='Enter'){if(active>=0&&rows[active]){e.preventDefault(); rows[active].click();}} if(e.key==='Escape'){e.preventDefault(); close();}}); inp.addEventListener('blur',()=>setTimeout(close,120)); window.addEventListener('resize',place); window.addEventListener('scroll',place,true);};

// A paired party selector keeps the displayed number, name, and internal ID atomic.
// It searches the already-loaded active master data, so typing never causes duplicate API calls.
const bindPartySelector=({numberId,nameId,hiddenId,items,kind,onPick})=>{const number=$(numberId),name=$(nameId),hidden=$(hiddenId);if(!number||!name||!hidden)return null;const activeItems=items.filter(x=>String(x.status||'Active').toLowerCase()==='active');const panel=document.createElement('div');panel.className='erp-lookup-panel hidden party-suggestions';const list=document.createElement('div');list.className='erp-lookup-list';panel.appendChild(list);document.body.appendChild(panel);let selected=activeItems.find(x=>x.id===hidden.value)||null,active=-1,shown=[],timer;const noun=kind==='vendor'?'vendors':'customers';const place=input=>{const r=input.getBoundingClientRect();panel.style.left=r.left+'px';panel.style.top=(r.bottom+2)+'px';panel.style.width=Math.max(r.width,360)+'px';};const close=()=>{panel.classList.add('hidden');active=-1;};const setValidity=message=>{number.setCustomValidity(message);name.setCustomValidity(message);};const pick=item=>{selected=item;number.value=item.id;name.value=item.name;hidden.value=item.id;setValidity('');close();onPick?.(item);};const render=(query,input)=>{const q=String(query||'').trim().toLowerCase();shown=q.length<1?[]:activeItems.filter(x=>String(x.id||'').toLowerCase().includes(q)||String(x.name||'').toLowerCase().includes(q)).slice(0,60);list.innerHTML=shown.length?shown.map((x,i)=>`<button type='button' class='erp-lookup-row ${i===active?'active':''}' data-i='${i}'><span class='erp-lookup-name'>${esc(x.name)}</span><span aria-hidden='true'> — </span><span class='erp-lookup-id'>${esc(x.id)}</span></button>`).join(''):`<div class='erp-lookup-empty'>No matching ${noun} found</div>`;list.querySelectorAll('button').forEach((row,i)=>{row.onpointerdown=e=>e.preventDefault();row.onclick=()=>pick(shown[i]);});panel.classList.remove('hidden');place(input);};const changed=input=>{setValidity(`Select a valid active ${kind}.`);clearTimeout(timer);timer=setTimeout(()=>render(input.value,input),180);};const keys=input=>e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(panel.classList.contains('hidden'))render(input.value,input);active=e.key==='ArrowDown'?Math.min(active+1,shown.length-1):Math.max(active-1,0);list.querySelectorAll('button').forEach((r,i)=>r.classList.toggle('active',i===active));}else if(e.key==='Enter'&&active>=0){e.preventDefault();pick(shown[active]);}else if(e.key==='Escape')close();};[number,name].forEach(input=>{input.classList.add('search-input');input.addEventListener('input',()=>changed(input));input.addEventListener('keydown',keys(input));input.addEventListener('focus',()=>{if(input.value!==selected?.id&&input.value!==selected?.name)changed(input);});});document.addEventListener('pointerdown',e=>{if(e.target!==number&&e.target!==name&&!panel.contains(e.target))close();});const validate=()=>{const match=activeItems.find(x=>x.id.toLowerCase()===number.value.trim().toLowerCase()&&x.name.toLowerCase()===name.value.trim().toLowerCase());if(match){pick(match);return true;}setValidity(`Select a valid active ${kind}.`);return false;};return{validate,get selected(){return selected;},pick};};
const bindApVendorSelector=({numberId,nameId,hiddenId,vendors,state,termsId,procurementId,onSelected})=>bindPartySelector({numberId,nameId,hiddenId,items:vendors,kind:'vendor',onPick:vendor=>{state.vendorId=vendor.id;state.vendorName=vendor.name;if(termsId&&$(termsId)&&vendor.terms)$(termsId).value=vendor.terms;if(procurementId&&$(procurementId))$(procurementId).value=vendor.assignedProcurementPersonUserId||vendor.assignedProcurementPerson||'';onSelected?.(vendor);}});
const parsePageSelection=(value,totalPages)=>{const maximum=Number(totalPages);if(!Number.isSafeInteger(maximum)||maximum<1)throw new Error('The source PDF page count is unavailable.');const input=String(value||'').trim();if(!input)throw new Error('Enter at least one page.');const pages=new Set();for(const token of input.split(',').map(part=>part.trim())){if(!token)throw new Error('Invalid page range: empty page value.');const match=token.match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!match)throw new Error(`Invalid page range: ${token}.`);const from=Number(match[1]),to=Number(match[2]||match[1]);if(!Number.isSafeInteger(from)||!Number.isSafeInteger(to)||from<1||to<1)throw new Error('Page numbers must be positive whole numbers.');if(from>to)throw new Error(`Invalid page range: ${token}. The first page must not exceed the last page.`);if(to>maximum)throw new Error(`Page ${to} exceeds the source PDF page count of ${maximum}.`);for(let page=from;page<=to;page++)pages.add(page);}const result=[...pages].sort((a,b)=>a-b);if(!result.length)throw new Error('Enter at least one page.');return result;};
const recognitionStatusHtml=doc=>{const status=String(doc.processingStatus||doc.status||'Queued'),normalized=status.toLowerCase();if(normalized==='processing')return `<span class='recognition-status processing' data-document-status='${esc(doc.id)}'><span class='recognition-spinner' aria-hidden='true'></span>Processing with Azure…</span>`;if(normalized==='queued')return `<span class='recognition-status queued' data-document-status='${esc(doc.id)}'><span aria-hidden='true'>◷</span> Queued</span>`;if(normalized==='ready for review')return `<span class='recognition-status ready' data-document-status='${esc(doc.id)}'><span aria-hidden='true'>✓</span> Ready for Review</span>`;if(normalized==='failed')return `<span class='recognition-status failed' data-document-status='${esc(doc.id)}' title='${esc(doc.processingError||'Recognition failed')}'>⚠ Failed</span>`;if(normalized==='split')return `<span class='recognition-status split' data-document-status='${esc(doc.id)}'>⑂ Split</span>`;return `<span class='recognition-status' data-document-status='${esc(doc.id)}'>${esc(status)}</span>`;};

