function periodStatusBadge(status){return `<span class='period-status ${String(status).toLowerCase()}'>${status}</span>`;}
function showPeriodBlockers(blockers){
  const overlay=document.createElement('div'); overlay.className='cn-overlay';
  overlay.innerHTML=`<div class='cn-modal period-blocker-modal'><div class='cn-head'><h3>Closing Validation</h3><p>Resolve these blocking transactions before closing the module period.</p></div><div class='cn-list'><table class='period-grid'><tr><th>Module</th><th>Document</th><th>Type</th><th>Status</th><th>Description</th></tr>${(blockers||[]).map(b=>`<tr><td>${b.module}</td><td><a class='link' href='${b.href||'#'}'>${b.id}</a></td><td>${b.type}</td><td>${b.status}</td><td>${b.description||''}</td></tr>`).join('')}</table></div><div class='cn-foot'><button id='closeBlockers'>Close</button></div></div>`;
  document.body.appendChild(overlay); overlay.querySelector('#closeBlockers').onclick=()=>overlay.remove();
}
async function postPeriodAction(payload){
  const r=await fetch('/api/finance/financial-periods/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}); const b=await r.json();
  if(!r.ok){ if(b.blockers) showPeriodBlockers(b.blockers); else alert(b.error||'Period action failed'); throw new Error(b.error||'Period action failed'); }
  return b;
}
async function renderYearEndFinancialPeriods(){
 const v=$('#view'),years=await api('/api/finance/year-end'),wanted=new URLSearchParams(location.search).get('year'),row=years.find(y=>y.year===wanted)||years[0];$('#title').textContent='Financial Periods (Year-End)';if(!row){v.innerHTML="<div class='panel'>No fiscal years configured.</div>";return;}const journal=row.pendingAdjustmentClosingJournal||row.closingJournal,history=(row.history||[]).slice().reverse();
 v.innerHTML=`<div class='year-end-screen' data-year='${esc(row.year)}' data-status='${esc(row.status)}'><div class='header-row'><h3>Fiscal Year ${esc(row.year)} — <span id='yearEndStatus'>${esc(row.status)}</span></h3><label>Year <select id='yearEndYear'>${years.map(y=>`<option ${y.year===row.year?'selected':''}>${esc(y.year)}</option>`).join('')}</select></label></div><section class='panel year-end-warning'><h4>Pre-close checklist and warnings</h4><label><input id='yearEndAck' type='checkbox'> I understand starting locks normal AP, AR, Inventory, PO, SO, Cash and GL posting for this year.</label><p>Retained Earnings / Equity: <b id='retainedEarningsConfig'>${esc(row.retainedEarningsAccount||'NOT CONFIGURED')} ${esc(row.retainedEarningsAccountTitle||'')}</b></p><label>Current Password <input id='yearEndPassword' type='password' autocomplete='current-password'></label><div class='erp-toolbar'><button id='yearEndStart'>Start Year-End Close</button><button id='yearEndCancel'>Cancel Close</button><button id='yearEndPost'>Post Closing Journal</button><button id='yearEndFinalize'>Confirm and Close Year</button><button id='yearEndRefresh'>Refresh</button></div></section>${journal?`<section class='panel'><h4>Review Saved Closing Journal <a id='yearEndJournalLink' class='link' href='/finance/journal/${esc(journal.jeNumber)}'>${esc(journal.jeNumber)}</a> — ${esc(journal.status)}</h4><table id='yearEndLines'><tr><th>Account</th><th>Description</th><th>Debit</th><th>Credit</th></tr>${journal.lines.map(l=>`<tr><td>${esc(l.account)}</td><td>${esc(l.lineDescription)}</td><td>${fmtMoney(l.debit)}</td><td>${fmtMoney(l.credit)}</td></tr>`).join('')}</table></section>`:''}<section class='panel'><h4>P&amp;L Zero Proof</h4><p id='yearEndPlTotal'>Net ${fmtMoney(row.profitAndLossTotal)}</p><table><tr><th>Account</th><th>Title</th><th>Balance</th></tr>${row.profitAndLossBalances.map(l=>`<tr><td>${esc(l.account)}</td><td>${esc(l.accountTitle)}</td><td>${fmtMoney(l.balance)}</td></tr>`).join('')||'<tr><td colspan="3">All P&amp;L balances are zero.</td></tr>'}</table></section><section id='auditAdjustmentPanel' class='panel ${row.status==='Closed'?'':'hidden'}'><h4>New Audit Adjustment</h4><div class='erp-header-grid'><label>Reason<input id='auditReason'></label><label>Reference<input id='auditReference'></label><label>Current Password<input id='auditPassword' type='password' autocomplete='current-password'></label></div><table><tr><th>Account</th><th>Debit</th><th>Credit</th><th>Description</th></tr>${[0,1].map(()=>`<tr><td><input class='audit-account'></td><td><input class='audit-debit' type='number' value='0'></td><td><input class='audit-credit' type='number' value='0'></td><td><input class='audit-description'></td></tr>`).join('')}</table><button id='auditCreate'>Create Saved Audit Adjustment</button><label>Saved Audit JE <input id='auditJeNumber'></label><button id='auditPost'>Post Audit Adjustment</button></section><section class='panel'><h4>Append-Only Year-End History</h4><table id='yearEndHistory'><tr><th>Timestamp</th><th>Action</th><th>Status</th><th>User</th></tr>${history.map(h=>`<tr><td>${esc(h.timestamp)}</td><td>${esc(h.action)}</td><td>${esc(h.status)}</td><td>${esc(h.userId)}</td></tr>`).join('')}</table></section></div>`;
 const reload=()=>navigateTo(`/finance/year-end-close?year=${row.year}`),password=()=>$('#yearEndPassword').value;$('#yearEndYear').onchange=()=>navigateTo(`/finance/year-end-close?year=${$('#yearEndYear').value}`);$('#yearEndRefresh').onclick=reload;
 $('#yearEndStart').onclick=async()=>{if(!$('#yearEndAck').checked)return alert('Acknowledge the year-end warning first.');await api(`/api/finance/year-end/${row.year}/start`,{method:'POST',body:JSON.stringify({acknowledged:true,password:password()})});reload();};$('#yearEndCancel').onclick=async()=>{if(confirm('Cancel this close before close accounting is posted?')){await api(`/api/finance/year-end/${row.year}/cancel`,{method:'POST',body:'{}'});reload();}};$('#yearEndPost').onclick=async()=>{if(confirm('Post the reviewed closing journal through the central GL posting engine?')){await api(`/api/finance/year-end/${row.year}/post-closing-journal`,{method:'POST',body:'{}'});reload();}};$('#yearEndFinalize').onclick=async()=>{if(!$('#yearEndAck').checked)return alert('Acknowledge the final warning first.');if(confirm('Final warning: permanently close this fiscal year to normal posting?')){await api(`/api/finance/year-end/${row.year}/finalize`,{method:'POST',body:JSON.stringify({password:password(),confirmed:true})});reload();}};
 if($('#auditCreate'))$('#auditCreate').onclick=async()=>{const lines=[...document.querySelectorAll('#auditAdjustmentPanel tr')].slice(1).map(tr=>({account:tr.querySelector('.audit-account').value,debit:Number(tr.querySelector('.audit-debit').value||0),credit:Number(tr.querySelector('.audit-credit').value||0),lineDescription:tr.querySelector('.audit-description').value})).filter(l=>l.account);const je=await api(`/api/finance/year-end/${row.year}/audit-adjustments`,{method:'POST',body:JSON.stringify({password:$('#auditPassword').value,reason:$('#auditReason').value,reference:$('#auditReference').value,requestId:`audit-${Date.now()}`,lines})});$('#auditJeNumber').value=je.jeNumber;};if($('#auditPost'))$('#auditPost').onclick=async()=>{await api(`/api/finance/year-end/${row.year}/audit-adjustments/post`,{method:'POST',body:JSON.stringify({jeNumber:$('#auditJeNumber').value})});reload();};if(row.status==='Audit Adjustment Closing In Progress'){const button=document.createElement('button');button.id='yearEndPostAdjustmentClose';button.textContent='Post Audit Adjustment Closing Journal';button.onclick=async()=>{await api(`/api/finance/year-end/${row.year}/post-adjustment-closing`,{method:'POST',body:'{}'});reload();};v.prepend(button);}
}
async function renderFinancialPeriods(){
  $('#title').textContent='Financial Periods'; const v=$('#view');
  const [periods,history]=await Promise.all([api('/api/finance/financial-periods'),api('/api/finance/financial-period-history')]);
  const selected=localStorage.getItem('selected_fin_period')||periods.find(p=>p.periodId===new Date().toISOString().slice(0,7))?.periodId||periods[0]?.periodId||'';
  const periodRows=periods.map(p=>({...p,selectedPick:`<input type='radio' name='periodPick' value='${p.periodId}' ${p.periodId===selected?'checked':''}>`,arStatusLabel:p.arStatus,apStatusLabel:p.apStatus,glStatusLabel:p.glStatus,inventoryStatusLabel:p.inventoryStatus,overallStatusLabel:p.overallStatus,closedDateDisplay:p.closedDate?new Date(p.closedDate).toLocaleString():''}));
  const historyRows=history.map(h=>({...h,dateTimeDisplay:new Date(h.dateTime).toLocaleString()}));
  v.innerHTML=`<div class='period-screen'>
<div class='erp-toolbar period-toolbar'>
<button id='periodSave'>Save</button>
<button id='periodOpen'>Open Period</button>
<button id='periodClose'>Close Period</button>
<button id='periodReopen'>Reopen Period</button>
<button id='periodCloseAll'>Close All Modules</button>
<button id='periodReopenAll'>Reopen All Modules</button>
<button id='periodRefresh'>Refresh</button>
</div>
<div class='erp-tabs'>
<button class='tab active' data-tab='periods'>Periods</button>
<button class='tab' data-tab='history'>Period History</button>
</div>
<div id='tab-periods' class='tab-pane'>${ErpDataGrid({id:'financialPeriodsGrid',savedViewKey:'financial-periods',rows:periodRows,checkboxSelection:false,columns:[{key:'selectedPick',label:'',render:r=>r.selectedPick},{key:'financialYear',label:'Financial Year'},{key:'periodId',label:'Period ID'},{key:'periodDescription',label:'Period Description'},{key:'startDate',label:'Start Date'},{key:'endDate',label:'End Date'},{key:'arStatusLabel',label:'AR Status',render:r=>periodStatusBadge(r.arStatus)},{key:'apStatusLabel',label:'AP Status',render:r=>periodStatusBadge(r.apStatus)},{key:'glStatusLabel',label:'GL Status',render:r=>periodStatusBadge(r.glStatus)},{key:'inventoryStatusLabel',label:'Inventory Status',render:r=>periodStatusBadge(r.inventoryStatus)},{key:'overallStatusLabel',label:'Overall Status',render:r=>periodStatusBadge(r.overallStatus)},{key:'closedBy',label:'Closed By'},{key:'closedDateDisplay',label:'Closed Date'}]})}</div>
<div id='tab-history' class='tab-pane hidden'>${ErpDataGrid({id:'financialPeriodHistoryGrid',savedViewKey:'financial-period-history',rows:historyRows,checkboxSelection:false,columns:[{key:'periodId',label:'Period ID'},{key:'module',label:'Module'},{key:'action',label:'Action'},{key:'previousStatus',label:'Previous Status'},{key:'newStatus',label:'New Status'},{key:'user',label:'User'},{key:'dateTimeDisplay',label:'Date/Time'},{key:'notes',label:'Notes'}]})}</div>
</div>`;
  bindGrid('financialPeriodsGrid'); bindGrid('financialPeriodHistoryGrid');
  const pick=()=>document.querySelector('input[name="periodPick"]:checked')?.value||selected;
  document.querySelectorAll('input[name="periodPick"]').forEach(r=>r.onchange=()=>{localStorage.setItem('selected_fin_period',r.value); renderFinancialPeriods();});
  document.querySelectorAll('.erp-tabs .tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.erp-tabs .tab').forEach(x=>x.classList.remove('active')); t.classList.add('active'); $('#tab-periods').classList.toggle('hidden',t.dataset.tab!=='periods'); $('#tab-history').classList.toggle('hidden',t.dataset.tab!=='history');});
  const chooseModule=(title)=>{const m=prompt(`${title}: AR, AP, GL, or Inventory`,'AR'); return ['AR','AP','GL','Inventory'].includes(m)?m:null;};
  $('#periodSave').onclick=()=>alert('Financial period settings are saved automatically.');
  $('#periodRefresh').onclick=router;
  $('#periodOpen').onclick=async()=>{const module=chooseModule('Open module'); if(!module) return; if(!confirm('Are you sure you want to open this financial period?')) return; await postPeriodAction({periodId:pick(),module,action:'Open'}); router();};
  $('#periodClose').onclick=async()=>{const module=chooseModule('Close module'); if(!module) return; await postPeriodAction({periodId:pick(),module,action:'Close'}).then(router).catch(()=>{});};
  $('#periodReopen').onclick=async()=>{const module=chooseModule('Reopen module'); if(!module) return; if(!confirm('Are you sure you want to reopen this period? This will allow posting into a previously closed period.')) return; await postPeriodAction({periodId:pick(),module,action:'Reopen'}); router();};
  $('#periodCloseAll').onclick=async()=>{if(!confirm('Close AR, AP, GL, and Inventory for the selected period?')) return; await postPeriodAction({periodId:pick(),module:'All',action:'Close'}).then(router).catch(()=>{});};
  $('#periodReopenAll').onclick=async()=>{if(!confirm('Are you sure you want to reopen this period? This will allow posting into a previously closed period.')) return; await postPeriodAction({periodId:pick(),module:'All',action:'Reopen'}); router();};
}

async function renderReclassificationScreen(v){
  const params=new URLSearchParams(location.search); const today=new Date().toISOString().slice(0,10); const current=today.slice(0,7); const sourceJe=params.get('sourceJe')||''; const sourceRef=params.get('sourceRef')||'';
  const coa=(await api('/api/finance/chart-of-accounts')).filter(a=>a.active!==false); const coaLookup=coa.map(a=>({id:a.accountNumber,name:a.accountTitle}));
  const accountValue=(raw)=>String(raw||'').trim().split(/\s+/)[0]; const accountDisplay=(code)=>{const a=coaLookup.find(x=>x.id===String(code||'')); return a?`${a.id}    ${a.name}`:String(code||'');};
  $('#title').textContent='Reclassification';
  v.innerHTML=`<div class='erp-toolbar sticky'><button id='rcLoad'>Load</button><button id='rcSplit'>Split</button><button id='rcProcess'>Process</button><button id='rcClose'>Close</button></div><section class='erp-workspace reclass-screen'><div id='rcSearch' class='panel hidden'><h4>Load JE Lines</h4><div class='erp-header-grid'><label>Account<input id='rcPopAccount' placeholder='Search account number or name'></label><label>Account To<input id='rcPopAccountTo' placeholder='Search account number or name'></label><label>From Period<input id='rcPopFrom' value='${params.get('fromPeriod')||current}'></label><label>To Period<input id='rcPopTo' value='${params.get('toPeriod')||current}'></label></div><button id='rcRunSearch'>Search</button><button id='rcCancelSearch'>Cancel</button></div><div class='table-wrap'><table id='rcGrid'><thead><tr><th><input id='rcAll' type='checkbox'></th><th>JE Reference</th><th>Source Module</th><th>Source Reference</th><th>Period</th><th>Account</th><th>Account To</th><th>Debit</th><th>Credit</th><th>Amount</th><th>Description</th></tr></thead><tbody></tbody></table></div><div id='rcMsg' class='panel muted'>Click Load to search posted journal entry lines, choose Account To, optionally Split, then Process.</div></section>`;
  let rows=[]; let lastSearch={account:params.get('account')||'',accountTo:params.get('accountTo')||'',fromPeriod:params.get('fromPeriod')||current,toPeriod:params.get('toPeriod')||current,sourceJe,sourceRef};
  const setMessage=()=>{const totals={}; rows.forEach(r=>{const key=r.originalId||r.id; totals[key]=totals[key]||{source:Number(r.originalAmount||r.amount||0),total:0}; totals[key].total+=Number(r.amount||0);}); const bad=Object.values(totals).filter(t=>Math.round((t.total-t.source)*100)!==0).length; $('#rcMsg').textContent=`Loaded ${rows.length} posted JE line(s).${bad?` ${bad} split group(s) do not tie to the original amount yet.`:''}`;};
  const bindAccountLookup=(selector,onPick)=>lookupFilter(selector,null,coaLookup,(m)=>{const input=$(selector); if(input) input.value=`${m.id}    ${m.name}`; onPick&&onPick(m);});
  const render=()=>{$('#rcGrid tbody').innerHTML=rows.map((r,i)=>`<tr data-i='${i}' data-original='${r.originalId||r.id}'><td><input class='rcPick' type='checkbox' ${r.checked?'checked':''}></td><td><a class='link' href='/finance/journal/${r.jeReference}'>${r.jeReference}</a></td><td>${r.sourceModule||''}</td><td>${r.sourceReference||''}</td><td>${r.period||''}</td><td>${r.accountName||accountDisplay(r.account)}</td><td><input id='rcTo_${i}' class='rcTo' value='${accountDisplay(r.accountTo)}' placeholder='Search account number or name'></td><td class='num'>${fmtMoney(r.debit)}</td><td class='num'>${fmtMoney(r.credit)}</td><td><input class='rcAmt' type='number' step='0.01' value='${Number(r.amount||0)}'></td><td><input class='rcDesc' value='${r.description||''}'></td></tr>`).join(''); document.querySelectorAll('#rcGrid tbody tr').forEach(tr=>{const i=Number(tr.dataset.i); tr.querySelector('.rcPick').onchange=e=>rows[i].checked=e.target.checked; tr.querySelector('.rcTo').oninput=e=>rows[i].accountTo=accountValue(e.target.value); tr.querySelector('.rcAmt').oninput=e=>{rows[i].amount=Number(e.target.value||0); setMessage();}; tr.querySelector('.rcDesc').oninput=e=>rows[i].description=e.target.value; bindAccountLookup(`#rcTo_${i}`,(m)=>rows[i].accountTo=m.id);}); setMessage();};
  const load=async()=>{const q=new URLSearchParams(lastSearch); rows=(await api('/api/finance/reclassify/search?'+q.toString())).map(r=>({...r,originalId:r.id,originalAmount:Number(r.amount||0),checked:false,accountTo:accountValue(lastSearch.accountTo)||r.accountTo||''})); render();};
  $('#rcLoad').onclick=()=>{ $('#rcSearch').classList.remove('hidden'); $('#rcPopAccount').value=accountDisplay(lastSearch.account); $('#rcPopAccountTo').value=accountDisplay(lastSearch.accountTo); $('#rcPopFrom').value=lastSearch.fromPeriod; $('#rcPopTo').value=lastSearch.toPeriod; };
  bindAccountLookup('#rcPopAccount',(m)=>lastSearch.account=m.id); bindAccountLookup('#rcPopAccountTo',(m)=>lastSearch.accountTo=m.id);
  $('#rcRunSearch').onclick=async()=>{lastSearch={...lastSearch,account:accountValue($('#rcPopAccount').value),accountTo:accountValue($('#rcPopAccountTo').value),fromPeriod:$('#rcPopFrom').value,toPeriod:$('#rcPopTo').value}; await load(); $('#rcSearch').classList.add('hidden');};
  $('#rcCancelSearch').onclick=()=>$('#rcSearch').classList.add('hidden'); $('#rcAll').onchange=e=>{rows.forEach(r=>r.checked=e.target.checked); render();};
  $('#rcSplit').onclick=()=>{const i=rows.findIndex(r=>r.checked); if(i<0) return alert('Check one line to split.'); const original=rows[i]; rows.splice(i+1,0,{...original,id:`${original.originalId||original.id}:split:${Date.now()}`,originalId:original.originalId||original.id,originalAmount:Number(original.originalAmount||original.amount||0),amount:0,checked:true,description:`Split of ${original.jeReference}`}); render();};
  $('#rcProcess').onclick=async()=>{const payload={toPeriod:lastSearch.toPeriod||current,transactionDate:`${lastSearch.toPeriod||current}-01`,lines:rows.filter(r=>r.checked).map(r=>({id:r.id,originalId:r.originalId||r.id,lineIndex:r.lineIndex,jeReference:r.jeReference,accountTo:accountValue(r.accountTo),amount:Number(r.amount||0),checked:true,description:r.description}))}; const je=await api('/api/finance/reclassify/process',{method:'POST',body:JSON.stringify(payload)}); alert(`Created and posted reclassification JE ${je.jeNumber}`); history.pushState({},'',`/finance/journal/${je.jeNumber}`); router();};
  $('#rcClose').onclick=()=>returnToValidatedOrigin('/finance/reclassify'); if(sourceJe||sourceRef) await load();
}


async function renderEmailSettings(){
  $('#title').textContent='Email Settings';
  const settings=await api('/api/finance/email-settings');
  const history=await api('/api/ar/invoices/send-history');
  const rows=history.slice().reverse().map(h=>({invoiceNumber:h.invoiceNumber,customer:h.customer,email:h.customerEmail,sentDate:h.sentDate?new Date(h.sentDate).toLocaleString():'',status:h.emailStatus,errorMessage:h.errorMessage||''}));
  $('#view').innerHTML=`<div class='header-row'><h3>Finance → Setup → Email Settings</h3></div><div class='panel'><p><b>Render environment variables:</b> SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS, SMTP_FROM. SMTP_FROM is optional and defaults to SMTP_USER.</p><p><b>Gmail:</b> Gmail requires App Passwords when 2FA is enabled.</p><div class='erp-header-grid'><label>SMTP Host<input id='smtpHost' value='${esc(settings.smtpHost)}' placeholder='smtp.gmail.com'></label><label>SMTP Port<input id='smtpPort' type='number' value='${esc(settings.smtpPort||587)}'></label><label>SMTP User<input id='smtpUser' value='${esc(settings.smtpUser)}' placeholder='yourcompanyemail@gmail.com'></label><label>SMTP Password<input id='smtpPass' type='password' placeholder='${settings.hasPassword?'Configured - leave blank to keep':'App password'}'></label><label>From Email<input id='fromEmail' value='${esc(settings.fromEmail)}' placeholder='Defaults to SMTP User'></label><label>Send Test Email To<input id='testEmail' placeholder='recipient@example.com'></label></div><div class='erp-toolbar'><button id='saveEmailSettings'>Save Settings</button><button id='sendTestEmail'>Send Test Email</button></div><div id='emailStatus' class='panel'>${settings.configured?'SMTP is configured.':'SMTP is not fully configured.'}</div></div><div class='panel'><h3>Email History Log</h3>${ErpDataGrid({id:'emailHistoryGrid',columns:[{key:'invoiceNumber',label:'Invoice Number'},{key:'customer',label:'Customer'},{key:'email',label:'Email'},{key:'sentDate',label:'Sent Date'},{key:'status',label:'Status'},{key:'errorMessage',label:'Error Message'}],rows})}</div>`;
  bindGrid('emailHistoryGrid');
  const payload=()=>({smtpHost:$('#smtpHost').value.trim(),smtpPort:$('#smtpPort').value.trim(),smtpUser:$('#smtpUser').value.trim(),smtpPass:$('#smtpPass').value,fromEmail:$('#fromEmail').value.trim()});
  $('#saveEmailSettings').onclick=async()=>{try{await api('/api/finance/email-settings',{method:'POST',body:JSON.stringify(payload())}); showErpDialog({title:'Email Settings Saved',message:'SMTP settings were saved for this running server session.',type:'success'}); router();}catch(e){showErpDialog({title:'Email Settings Error',message:'SMTP settings could not be saved.',details:e.message,type:'error'});}};
  $('#sendTestEmail').onclick=async()=>{const to=$('#testEmail').value.trim(); if(!to) return showErpDialog({title:'Test Email Required',message:'Enter a recipient email address.',type:'error'}); const body={...payload(),to}; const r=await fetch('/api/finance/email-settings/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}); const b=await r.json(); if(r.ok){showErpDialog({title:'Test Email Sent',message:b.message,type:'success'}); router();} else {showErpDialog({title:'Test Email Failed',message:'The SMTP provider rejected the test email.',details:b.error||'Unknown SMTP error',type:'error'});} };
}

const soFmt=(n)=>Number(n||0).toLocaleString(undefined,{style:'currency',currency:'USD'});
const soStatusBadge=(s)=>`<span class='so-status so-${String(s||'').toLowerCase().replaceAll(' ','-')}'>${esc(s||'')}</span>`;
function soToolbar(doc={}){ const st=doc.status||'Draft'; const hasShip=(doc.shipments||[]).length>0, hasInv=(doc.invoices||[]).length>0; const available=(doc.lines||[]).some(l=>Number(l.qtyOrdered)>Number(l.qtyShipped)&&Number(l.qtyAllocated)>0); const invoiceable=(doc.lines||[]).some(l=>Number(l.qtyShipped)>Number(l.qtyInvoiced)||(['ITEM-1005'].includes(l.itemId)&&Number(l.qtyOrdered)>Number(l.qtyInvoiced))); return `<div class='erp-toolbar so-toolbar sticky'><button id='soBack'>Back</button><button id='soSaveClose'>Save & Close</button><button id='soSave'>Save</button><button id='soNew'>New</button><button id='soDelete' ${st==='Saved'&&!hasShip&&!hasInv?'':'disabled'}>Delete</button><button id='soHold' ${['Open','Saved'].includes(st)?'':'disabled'}>Hold</button><button id='soRemoveHold' ${['On Hold','Credit Hold'].includes(st)?'':'disabled'}>Remove Hold</button><button id='soConfirm' ${['Saved','Draft','On Hold'].includes(st)?'':'disabled'}>Confirm</button><button id='soCreateShipment' ${st==='Open'&&available?'':'disabled'}>Create Shipment</button><button id='soPrepareInvoice' ${invoiceable&&!['Credit Hold','Cancelled','Voided'].includes(st)?'':'disabled'}>Prepare Invoice</button><button id='soCancel' ${!['Shipped','Invoiced','Closed','Cancelled','Voided'].includes(st)?'':'disabled'}>Cancel Order</button><select id='soActions'><option>Actions</option><option>Release SO Documents</option></select><select id='soInquiries'><option>Inquiries</option><option>Order Inquiry</option><option>Shipment Inquiry</option><option>Backorder Inquiry</option></select><select id='soReports'><option>Reports</option><option>Open Sales Orders</option><option>Backorders</option><option>Orders Pending Shipment</option></select><button>|&lt;</button><button>&lt;</button><button>&gt;</button><button>&gt;|</button></div>`; }
async function renderSalesOrderList(){ const rows=await api('/api/sales-orders'); $('#title').textContent='Sales Orders'; configureRecordNavigationList({contextKey:'SALES_ORDERS',module:'Sales Orders',listUrl:'/sales-orders/orders',gridId:'soGrid',records:rows.map(r=>({id:r.orderNumber,type:'Sales Order',detailUrl:`/sales-orders/orders/${encodeURIComponent(r.orderNumber)}`}))}); $('#view').innerHTML=`<div class='header-row'><h3>Sales Orders</h3><div><a href='/sales-orders/orders/new'><button>New Sales Order</button></a><a href='/sales-orders/process-orders'><button>Process Orders</button></a></div></div>${ErpDataGrid({id:'soGrid',columns:[{key:'orderNumber',label:'Order Number',render:r=>`<a class='link' href='/sales-orders/orders/${r.orderNumber}'>${r.orderNumber}</a>`},{key:'orderType',label:'Order Type'},{key:'customerName',label:'Customer'},{key:'customerPO',label:'Customer PO'},{key:'orderDate',label:'Order Date'},{key:'requestedShipDate',label:'Requested Ship Date'},{key:'status',label:'Status',render:r=>soStatusBadge(r.status)},{key:'orderTotal',label:'Order Total'},{key:'openBalance',label:'Open Amount'},{key:'shippedAmount',label:'Shipped Amount'},{key:'invoicedAmount',label:'Invoiced Amount'},{key:'warehouse',label:'Warehouse'}],rows})}`; bindGrid('soGrid'); }
async function renderSalesOrderOverview(){ const rows=await api('/api/sales-orders'); const open=rows.filter(o=>['Open','Partially Shipped','Saved','Credit Hold'].includes(o.status)); $('#title').textContent='Sales Order Overview'; $('#view').innerHTML=`<div class='grid4'><section class='panel'><h3>Enter</h3><ul><li><a href='/sales-orders/orders'>Sales Orders</a></li><li><a href='/sales-orders/shipments'>Shipments</a></li><li><a href='/sales-orders/invoices'>Invoices</a></li></ul></section><section class='panel'><h3>Processes</h3><ul><li><a href='/sales-orders/process-orders'>Process Orders</a></li><li><a href='/sales-orders/create-shipments'>Create Shipments</a></li><li><a href='/sales-orders/prepare-invoices'>Prepare Invoices</a></li><li><a href='/sales-orders/release'>Release SO Documents</a></li></ul></section><section class='panel kpi'><h3>Open Orders</h3><div class='big'>${open.length}</div><p>${soFmt(open.reduce((s,o)=>s+Number(o.openBalance||0),0))} open balance</p></section><section class='panel kpi'><h3>Credit Holds</h3><div class='big'>${rows.filter(o=>o.status==='Credit Hold').length}</div><p>Blocked from shipment/invoice until released.</p></section></div>${ErpDataGrid({id:'soOverviewGrid',columns:[{key:'orderNumber',label:'Order',render:r=>`<a class='link' href='/sales-orders/orders/${r.orderNumber}'>${r.orderNumber}</a>`},{key:'customerName',label:'Customer'},{key:'status',label:'Status',render:r=>soStatusBadge(r.status)},{key:'orderTotal',label:'Total'},{key:'openBalance',label:'Open'}],rows:open})}`; bindGrid('soOverviewGrid'); }
function soLineRows(lines,items,editable){ return `<div class='table-wrap'><table class='so-line-grid'><tr><th>Line Number</th><th>Branch</th><th>Warehouse</th><th>Inventory ID</th><th>Description</th><th>Quantity Ordered</th><th>Qty Available</th><th>Quantity Allocated</th><th>Quantity Shipped</th><th>Quantity Invoiced</th><th>Quantity Backordered</th><th>UOM</th><th>Unit Price</th><th>Discount %</th><th>Discount Amount</th><th>Tax</th><th>Extended Price</th><th>Line Total</th><th>Revenue Account</th><th>COGS Account</th><th>Inventory Account</th><th>Status</th>${editable?'<th></th>':''}</tr>${lines.map((l,i)=>`<tr data-i='${i}'><td>${i+1}</td><td><input class='sl-branch' value='${esc(l.branch||'100')}' ${editable?'':'readonly'}></td><td><input class='sl-wh' value='${esc(l.warehouse||'MAIN')}' ${editable?'':'readonly'}></td><td><input class='sl-item search-input' value='${esc(l.itemId||l.inventoryId||'')}' ${editable?'':'readonly'}></td><td><input class='sl-desc' value='${esc(l.lineDescription||l.description||l.itemId||l.inventoryId||'')}' maxlength='255' ${editable?'':'readonly'}></td><td><input class='sl-qty' type='number' value='${Number(l.qtyOrdered||0)}' ${editable?'':'readonly'}></td><td><input class='sl-avail' type='number' value='${Number(l.qtyAvailable||0)}' readonly></td><td><input class='sl-alloc' type='number' value='${Number(l.qtyAllocated||0)}' readonly></td><td><input class='sl-ship' type='number' value='${Number(l.qtyShipped||0)}' readonly></td><td><input class='sl-inv' type='number' value='${Number(l.qtyInvoiced||0)}' readonly></td><td><input class='sl-back' type='number' value='${Number(l.qtyBackordered||0)}' readonly></td><td><input class='sl-uom' value='${esc(l.uom||'EA')}' ${editable?'':'readonly'}></td><td><input class='sl-price' type='number' value='${Number(l.unitPrice||0)}' ${editable?'':'readonly'}></td><td><input class='sl-discp' type='number' value='${Number(l.discountPct||0)}' ${editable?'':'readonly'}></td><td class='calc-disc'>${Number(l.discountAmount||0).toFixed(2)}</td><td><input class='sl-tax' type='number' value='${Number(l.tax||0)}' ${editable?'':'readonly'}></td><td class='calc-ext'>${Number(l.extendedPrice||0).toFixed(2)}</td><td class='calc-total'>${Number(l.lineTotal||0).toFixed(2)}</td><td><input class='sl-rev' value='${esc(l.revenueAccount||'4008')}' ${editable?'':'readonly'}></td><td><input class='sl-cogs' value='${esc(l.cogsAccount||'')}' ${editable?'':'readonly'}></td><td><input class='sl-invacct' value='${esc(l.inventoryAccount||'')}' ${editable?'':'readonly'}></td><td>${esc(l.status||'Open')}</td>${editable?`<td><button class='sl-del' type='button'>Delete</button></td>`:''}</tr>`).join('')}</table></div>${editable?"<button type='button' id='soAddLine'>+ Add Line</button>":''}`; }
async function renderSalesOrderDetail(id){ const isNew=id==='new'; const [customers,items]=await Promise.all([api('/api/sales-orders/customers'),api('/api/inventory/items')]); let doc=isNew?{orderType:'SO',orderNumber:'',status:'Draft',orderDate:new Date().toISOString().slice(0,10),requestedShipDate:new Date().toISOString().slice(0,10),postDate:new Date().toISOString().slice(0,10),postPeriod:new Date().toISOString().slice(0,7),branch:'100',warehouse:'MAIN',currency:'USD',terms:'NET30',shipVia:'UPS Ground',fobPoint:'Origin',freight:0,lines:[]}:await api('/api/sales-orders/'+id); let lines=(doc.lines||[]).map(x=>({...x})); const editable=!['Closed','Cancelled','Voided'].includes(doc.status); const customerDisplay=doc.customerId?`${doc.customerId}    ${doc.customerName}`:''; $('#title').textContent=isNew?'New Sales Order':`Sales Order ${doc.orderNumber}`; $('#view').innerHTML=`${soToolbar(doc)}<section class='erp-workspace so-screen'><div class='so-warning ${doc.creditWarning?'':'hidden'}'>${esc(doc.creditWarning||'')}</div><div class='erp-header-grid so-header'><label class='required'>Order Type<input id='soOrderType' value='${esc(doc.orderType||'SO')}' ${editable?'':'readonly'}></label><label>Sales Order Number<input id='soOrderNumber' value='${esc(doc.orderNumber||'')}' readonly></label><label>Status<input id='soStatus' value='${esc(doc.status||'Draft')}' readonly></label><label class='required'>Order Date<input id='soOrderDate' type='date' value='${esc(doc.orderDate||'')}' ${editable?'':'readonly'}></label><label>Requested Ship Date<input id='soReqDate' type='date' value='${esc(doc.requestedShipDate||'')}' ${editable?'':'readonly'}></label><label>Post Date<input id='soPostDate' type='date' value='${esc(doc.postDate||doc.orderDate||'')}' ${editable?'':'readonly'}></label><label>Post Period<input id='soPostPeriod' value='${esc(doc.postPeriod||'')}' readonly></label><label>Customer PO Number<input id='soCustomerPO' value='${esc(doc.customerPO||'')}' ${editable?'':'readonly'}></label><label>Description<input id='soDescription' value='${esc(doc.description||'')}' ${editable?'':'readonly'}></label><label class='required'>Customer<input id='soCustomerLookup' class='search-input' value='${esc(customerDisplay)}' ${editable?'':'readonly'}><input id='soCustomerId' type='hidden' value='${esc(doc.customerId||'')}'></label><label>Branch<input id='soBranch' value='${esc(doc.branch||'100')}' ${editable?'':'readonly'}></label><label>Warehouse<input id='soWarehouse' value='${esc(doc.warehouse||'MAIN')}' ${editable?'':'readonly'}></label><label>Currency<input id='soCurrency' value='${esc(doc.currency||'USD')}' ${editable?'':'readonly'}></label><label>Terms<input id='soTerms' value='${esc(doc.terms||'NET30')}' ${editable?'':'readonly'}></label><label>Due Date<input id='soDueDate' type='date' value='${esc(doc.dueDate||'')}' ${editable?'':'readonly'}></label><label>Ship Via<input id='soShipVia' value='${esc(doc.shipVia||'')}' ${editable?'':'readonly'}></label><label>FOB Point<input id='soFob' value='${esc(doc.fobPoint||'')}' ${editable?'':'readonly'}></label><label>Line Total<input id='soLineTotal' value='${Number(doc.lineTotal||0).toFixed(2)}' readonly></label><label>Discount Total<input id='soDiscountTotal' value='${Number(doc.discountTotal||0).toFixed(2)}' readonly></label><label>Tax Total<input id='soTaxTotal' value='${Number(doc.taxTotal||0).toFixed(2)}' readonly></label><label>Freight<input id='soFreight' type='number' value='${Number(doc.freight||0)}' ${editable?'':'readonly'}></label><label>Order Total<input id='soOrderTotal' value='${Number(doc.orderTotal||0).toFixed(2)}' readonly></label><label>Open Balance<input id='soOpenBalance' value='${Number(doc.openBalance||0).toFixed(2)}' readonly></label><label>Invoiced Amount<input id='soInvoicedAmount' value='${Number(doc.invoicedAmount||0).toFixed(2)}' readonly></label></div><div id='soCustomerInfo' class='panel muted'></div><div class='erp-tabs'>${['Document Details','Shipping','Billing','Financial Details','Taxes','Discounts','Shipments','Invoices','Applications','Notes / Attachments'].map((t,i)=>`<button class='tab ${i?'':'active'}' data-tab='${i}'>${t}</button>`).join('')}</div><div id='soTab0' class='tab-pane'>${soLineRows(lines,items,editable)}</div><div id='soTab1' class='tab-pane hidden'><div class='grid4'><section class='panel'><h3>Shipping</h3><p>Ship Via: ${esc(doc.shipVia||'')}</p><p>Warehouse: ${esc(doc.warehouse||'MAIN')}</p><p>Instructions: <textarea id='soShipInstr' ${editable?'':'readonly'}>${esc(doc.shippingInstructions||'')}</textarea></p></section></div></div><div id='soTab2' class='tab-pane hidden'><div class='panel'>Billing Address: ${esc(doc.customer?.billingAddress||'')}<br>Terms: ${esc(doc.terms||'')}</div></div><div id='soTab3' class='tab-pane hidden'><div class='panel'>Sales order save/open: no GL posting. Shipment release posts Inventory/COGS. Invoice post posts AR/revenue. Payment post uses AR cash/AR posting.</div></div><div id='soTab4' class='tab-pane hidden'><div class='panel'>Tax Total: <b>${soFmt(doc.taxTotal||0)}</b></div></div><div id='soTab5' class='tab-pane hidden'><div class='panel'>Discount Total: <b>${soFmt(doc.discountTotal||0)}</b></div></div><div id='soTab6' class='tab-pane hidden'><table><tr><th>Shipment Number</th><th>Ship Date</th><th>Status</th><th>Tracking Number</th><th>Freight</th></tr>${(doc.shipments||[]).map(s=>`<tr><td><a class='link' href='/sales-orders/shipments/${esc(s.id||s.shipmentNumber)}'>${s.shipmentNumber}</a></td><td>${s.shipDate}</td><td>${s.status}</td><td>${s.trackingNumber||''}</td><td>${soFmt(s.freightAmount||0)}</td></tr>`).join('')}</table></div><div id='soTab7' class='tab-pane hidden'><table><tr><th>Invoice Number</th><th>Invoice Date</th><th>Invoice Amount</th><th>Open Balance</th><th>Status</th><th>AR Reference</th><th>Drillable Link</th></tr>${(doc.invoices||[]).map(i=>`<tr><td>${i.invoiceNumber}</td><td>${i.invoiceDate}</td><td>${soFmt(i.invoiceAmount)}</td><td>${soFmt(i.openBalance)}</td><td>${i.status}</td><td>${i.arReference}</td><td><a class='link' href='/ar/doc/${i.invoiceId}'>Open AR Invoice</a></td></tr>`).join('')}</table></div><div id='soTab8' class='tab-pane hidden'><h4>Payments / Applications</h4><table><tr><th>Payment Reference</th><th>Application Date</th><th>Applied Amount</th><th>Remaining Order Balance</th><th>Status</th></tr>${(doc.payments||[]).map(p=>`<tr><td><a class='link' href='/ar/doc/${p.paymentId}'>${p.paymentRef||p.paymentId}</a></td><td>${p.applicationDate||''}</td><td>${soFmt(p.appliedAmount||0)}</td><td>${soFmt(p.orderOpenBalanceAfter??doc.openBalance??0)}</td><td>${p.status||''}</td></tr>`).join('')||`<tr><td colspan='5'>No sales order payment applications.</td></tr>`}</table></div><div id='soTab9' class='tab-pane hidden'><label>Notes<textarea id='soNotes' ${editable?'':'readonly'}>${esc(doc.notes||'')}</textarea></label><label>Internal Comments<textarea id='soInternal' ${editable?'':'readonly'}>${esc(doc.internalComments||'')}</textarea></label><div class='panel'>Customer PO Attachment: ${(doc.attachments||[]).map(a=>esc(a.name)).join(', ')||'None'}</div></div></section>`; const refreshCustomerInfo=()=>{const c=customers.find(x=>x.id===$('#soCustomerId').value); $('#soCustomerInfo').innerHTML=c?`<b>${c.id} ${c.name}</b> | Terms ${c.terms} | Tax Zone ${c.taxZone||''} | Credit Limit ${soFmt(c.creditLimit||0)} | Open AR Balance ${soFmt(c.openArBalance||0)} | Credit Hold ${c.creditHold?'Yes':'No'}<br>Billing: ${esc(c.billingAddress||'')}<br>Shipping: ${esc(c.shippingAddress||'')}`:'Select a customer to load terms, addresses, tax zone, credit limit, credit hold status, and open AR balance.';}; lookupFilter('#soCustomerLookup',null,customers,(c)=>{$('#soCustomerId').value=c.id; $('#soTerms').value=c.terms||'NET30'; $('#soCurrency').value=c.currency||'USD'; refreshCustomerInfo();}); refreshCustomerInfo(); document.querySelectorAll('.erp-tabs .tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.erp-tabs .tab').forEach(x=>x.classList.remove('active')); b.classList.add('active'); document.querySelectorAll('.tab-pane').forEach((p,i)=>p.classList.toggle('hidden',String(i)!==b.dataset.tab));}); const recalc=()=>{ lines=[...document.querySelectorAll('.so-line-grid tr[data-i]')].map((r,i)=>{const item=items.find(it=>it.code===r.querySelector('.sl-item').value.trim())||{}; const qty=Number(r.querySelector('.sl-qty').value||0), price=Number(r.querySelector('.sl-price').value||0), pct=Number(r.querySelector('.sl-discp').value||0), tax=Number(r.querySelector('.sl-tax').value||0); const ext=qty*price, disc=ext*pct/100, total=ext-disc+tax; r.querySelector('.calc-ext').textContent=ext.toFixed(2); r.querySelector('.calc-disc').textContent=disc.toFixed(2); r.querySelector('.calc-total').textContent=total.toFixed(2); return {lineNumber:i+1,branch:r.querySelector('.sl-branch').value,warehouse:r.querySelector('.sl-wh').value,itemId:r.querySelector('.sl-item').value.trim(),inventoryId:r.querySelector('.sl-item').value.trim(),description:r.querySelector('.sl-desc').value,qtyOrdered:qty,qtyAllocated:Number(r.querySelector('.sl-alloc').value||0),qtyShipped:Number(r.querySelector('.sl-ship').value||0),qtyInvoiced:Number(r.querySelector('.sl-inv').value||0),qtyBackordered:Number(r.querySelector('.sl-back').value||0),uom:r.querySelector('.sl-uom').value,unitPrice:price,discountPct:pct,discountAmount:disc,tax,extendedPrice:ext,lineTotal:total,revenueAccount:r.querySelector('.sl-rev').value||item.revenueAccount||'4008',cogsAccount:r.querySelector('.sl-cogs').value||item.cogsAccount||'',inventoryAccount:r.querySelector('.sl-invacct').value||item.inventoryAccount||'',status:'Open'};}); const sums=lines.reduce((a,l)=>({line:a.line+l.extendedPrice,disc:a.disc+l.discountAmount,tax:a.tax+l.tax,total:a.total+l.lineTotal}),{line:0,disc:0,tax:0,total:0}); sums.total+=Number($('#soFreight').value||0); $('#soLineTotal').value=sums.line.toFixed(2); $('#soDiscountTotal').value=sums.disc.toFixed(2); $('#soTaxTotal').value=sums.tax.toFixed(2); $('#soOrderTotal').value=sums.total.toFixed(2); $('#soOpenBalance').value=(sums.total-Number($('#soInvoicedAmount').value||0)).toFixed(2); }; const bindLines=()=>{document.querySelectorAll('.so-line-grid tr[data-i]').forEach((r,i)=>{r.onchange=recalc; const itemInput=r.querySelector('.sl-item'); lookupFilter(`#soTab0 tr[data-i='${i}'] .sl-item`,null,items.map(it=>({id:it.code,name:it.name,...it})),(it)=>{itemInput.value=it.code; r.querySelector('.sl-desc').value=it.description||it.name; r.querySelector('.sl-uom').value=it.uom||'EA'; r.querySelector('.sl-price').value=Number(it.salesPrice||0); r.querySelector('.sl-rev').value=it.revenueAccount||'4008'; r.querySelector('.sl-cogs').value=it.cogsAccount||''; r.querySelector('.sl-invacct').value=it.inventoryAccount||''; const av=r.querySelector('.sl-avail'); if(av) av.value=Number(it.qtyAvailable||0); const al=r.querySelector('.sl-alloc'); const ba=r.querySelector('.sl-back'); const q=Number(r.querySelector('.sl-qty').value||0); if(al) al.value=Math.min(q,Number(it.qtyAvailable||0)); if(ba) ba.value=Math.max(0,q-Number(it.qtyAvailable||0)); recalc();}); const del=r.querySelector('.sl-del'); if(del) del.onclick=()=>{lines.splice(i,1); document.querySelector('#soTab0').innerHTML=soLineRows(lines,items,editable); bindLines(); recalc();};});}; bindLines(); if($('#soAddLine')) $('#soAddLine').onclick=()=>{lines.push({branch:'100',warehouse:'MAIN',qtyOrdered:1,unitPrice:0,uom:'EA'}); document.querySelector('#soTab0').innerHTML=soLineRows(lines,items,editable); bindLines(); recalc();}; const payload=()=>({orderType:$('#soOrderType').value,orderDate:$('#soOrderDate').value,requestedShipDate:$('#soReqDate').value,postDate:$('#soPostDate').value,customerPO:$('#soCustomerPO').value,description:$('#soDescription').value,customerId:$('#soCustomerId').value,branch:$('#soBranch').value,warehouse:$('#soWarehouse').value,currency:$('#soCurrency').value,terms:$('#soTerms').value,dueDate:$('#soDueDate').value,shipVia:$('#soShipVia').value,fobPoint:$('#soFob').value,freight:Number($('#soFreight').value||0),shippingInstructions:$('#soShipInstr')?.value||'',notes:$('#soNotes')?.value||'',internalComments:$('#soInternal')?.value||'',status:isNew?'Saved':doc.status,lines}); const save=async(close=false)=>{recalc(); const res=isNew?await api('/api/sales-orders',{method:'POST',body:JSON.stringify(payload())}):await api('/api/sales-orders/'+doc.id,{method:'PUT',body:JSON.stringify(payload())}); if(res.warning) alert(res.warning); if(close) saveAndReturnToOrigin({canonicalFallback:'/sales-orders/orders'}); else navigateTo('/sales-orders/orders/'+res.orderNumber);}; $('#soBack').onclick=()=>returnToValidatedOrigin('/sales-orders/orders'); $('#soNew').onclick=()=>navigateTo('/sales-orders/orders/new'); $('#soSave').onclick=()=>save(false); $('#soSaveClose').onclick=()=>save(true); $('#soDelete').onclick=async()=>{await api('/api/sales-orders/'+doc.id,{method:'DELETE'}); navigateTo('/sales-orders/orders');}; const action=(a)=>api('/api/sales-orders/action',{method:'POST',body:JSON.stringify({id:doc.id,action:a})}).then(()=>router()); $('#soHold').onclick=()=>action('Hold'); $('#soRemoveHold').onclick=()=>action('Remove Hold'); $('#soConfirm').onclick=()=>action('Confirm'); $('#soCancel').onclick=()=>action('Cancel'); $('#soCreateShipment').onclick=async()=>{if(confirm('Create and confirm shipment from available order lines?')){await api('/api/sales-orders/create-shipment',{method:'POST',body:JSON.stringify({salesOrderId:doc.id,confirm:true})}); router();}}; $('#soPrepareInvoice').onclick=async()=>{const r=await api('/api/sales-orders/prepare-invoice',{method:'POST',body:JSON.stringify({salesOrderId:doc.id,shipmentId:(doc.shipments||[])[0]?.id||''})}); alert('Prepared AR invoice '+r.invoice.id); router();}; if(!isNew)bindRecordNavigationControls(); }
async function renderSoProcessOrders(){ const rows=await api('/api/sales-orders/process-orders'); $('#title').textContent='Process Orders'; $('#view').innerHTML=`<div class='header-row'><h3>Process Orders</h3><div><button id='poCreate'>Create Shipment</button><button id='poInvoice'>Prepare Invoice</button><button id='poHold'>Put On Hold</button><button id='poRelease'>Remove Hold</button><button id='poCancel'>Cancel Order</button><button id='poRefresh'>Refresh</button></div></div>${ErpDataGrid({id:'soProcGrid',columns:[{key:'orderNumber',label:'Order Number',render:r=>`<a class='link' href='/sales-orders/orders/${r.orderNumber}'>${r.orderNumber}</a>`},{key:'customerName',label:'Customer'},{key:'orderDate',label:'Order Date'},{key:'requestedShipDate',label:'Requested Ship Date'},{key:'status',label:'Status',render:r=>soStatusBadge(r.status)},{key:'orderTotal',label:'Order Total'},{key:'openAmount',label:'Open Amount'},{key:'qtyOrdered',label:'Qty Ordered'},{key:'qtyShipped',label:'Qty Shipped'},{key:'qtyBackordered',label:'Qty Backordered'},{key:'creditHold',label:'Credit Hold'},{key:'warehouse',label:'Warehouse'}],rows})}`; bindGrid('soProcGrid'); const selected=()=>[...document.querySelectorAll('#soProcGrid .grid-row:checked')].map(c=>c.closest('tr').children[1].textContent); $('#poRefresh').onclick=router; $('#poCreate').onclick=async()=>{for(const id of selected()) await api('/api/sales-orders/create-shipment',{method:'POST',body:JSON.stringify({salesOrderId:id,confirm:true})}); router();}; $('#poInvoice').onclick=async()=>{for(const id of selected()) try{await api('/api/sales-orders/prepare-invoice',{method:'POST',body:JSON.stringify({salesOrderId:id})});}catch(e){alert(`${id}: ${e.message}`)} router();}; $('#poHold').onclick=async()=>{for(const id of selected()) await api('/api/sales-orders/action',{method:'POST',body:JSON.stringify({id,action:'Hold'})}); router();}; $('#poRelease').onclick=async()=>{for(const id of selected()) await api('/api/sales-orders/action',{method:'POST',body:JSON.stringify({id,action:'Remove Hold'})}); router();}; $('#poCancel').onclick=async()=>{for(const id of selected()) await api('/api/sales-orders/action',{method:'POST',body:JSON.stringify({id,action:'Cancel'})}); router();}; }

async function renderShipmentDetail(id){
  const sh=await api('/api/sales-orders/shipments/'+encodeURIComponent(id));
  $('#title').textContent=`Shipment ${sh.shipmentNumber}`;
  $('#view').innerHTML=`<div class='erp-toolbar sticky'><button id='shipBack'>Back</button><a href='/sales-orders/shipments'><button>Shipment List</button></a><a href='/sales-orders/orders/${esc(sh.salesOrderNumber)}'><button>Sales Order</button></a></div><section class='erp-workspace'><div class='erp-header-grid'><label>Shipment Number<input readonly value='${esc(sh.shipmentNumber||'')}'></label><label>Sales Order Number<a class='link' href='/sales-orders/orders/${esc(sh.salesOrderNumber||'')}'>${esc(sh.salesOrderNumber||'')}</a></label><label>Customer<input readonly value='${esc(sh.customerName||'')}'></label><label>Ship Date<input readonly value='${esc(sh.shipDate||'')}'></label><label>Warehouse<input readonly value='${esc(sh.warehouse||'')}'></label><label>Ship Via<input readonly value='${esc(sh.shipVia||'')}'></label><label>Tracking Number<input readonly value='${esc(sh.trackingNumber||'')}'></label><label>Status<input readonly value='${esc(sh.status||'')}'></label><label>Freight Amount<input readonly value='${fmtMoney(sh.freightAmount||0)}'></label></div><div class='erp-tabs'>${['Shipment Lines','Sales Order','Inventory Transactions','Invoices','Financial Details'].map((t,i)=>`<button class='tab ${i?'':'active'}' data-tab='${i}'>${t}</button>`).join('')}</div><div id='shipTab0' class='tab-pane'>${ErpDataGrid({id:'shipLinesGrid',rows:sh.lines||[],checkboxSelection:false,columns:[{key:'inventoryId',label:'Inventory ID'},{key:'description',label:'Description'},{key:'orderedQty',label:'Ordered Qty'},{key:'shippedQty',label:'Shipped Qty'},{key:'backorderQty',label:'Backorder Qty'},{key:'uom',label:'UOM'},{key:'warehouse',label:'Warehouse'},{key:'location',label:'Location'}]})}</div><div id='shipTab1' class='tab-pane hidden'>${ErpDataGrid({id:'shipSoGrid',rows:[sh],checkboxSelection:false,columns:[{key:'salesOrderNumber',label:'Sales Order Number'},{key:'customerName',label:'Customer'},{key:'shipDate',label:'Ship Date'},{key:'status',label:'Shipment Status'}]})}</div><div id='shipTab2' class='tab-pane hidden'>${ErpDataGrid({id:'shipInvTxnGrid',rows:sh.inventoryTransactions||[],checkboxSelection:false,columns:[{key:'transactionId',label:'Inventory Transaction'},{key:'transactionType',label:'Type'},{key:'referenceNumber',label:'Reference'},{key:'sourceReference',label:'Source Reference'},{key:'itemId',label:'Inventory ID'},{key:'warehouse',label:'Warehouse'},{key:'location',label:'Location'},{key:'quantityIn',label:'Qty In'},{key:'quantityOut',label:'Qty Out'},{key:'unitCost',label:'Unit Cost'},{key:'extendedCost',label:'Extended Cost'},{key:'postDate',label:'Post Date'},{key:'jeReference',label:'JE Reference'}]})}</div><div id='shipTab3' class='tab-pane hidden'>${ErpDataGrid({id:'shipInvoicesGrid',rows:sh.invoices||[],checkboxSelection:false,columns:[{key:'invoiceNumber',label:'Invoice Number'},{key:'invoiceDate',label:'Invoice Date'},{key:'invoiceAmount',label:'Invoice Amount'},{key:'openBalance',label:'Open Balance'},{key:'status',label:'Status'},{key:'arReference',label:'AR Reference'}]})}</div><div id='shipTab4' class='tab-pane hidden'>${ErpDataGrid({id:'shipFinancialGrid',rows:sh.financialDetails||[],checkboxSelection:false,columns:[{key:'jeNumber',label:'JE Reference'},{key:'account',label:'Account'},{key:'description',label:'Description'},{key:'debit',label:'Debit'},{key:'credit',label:'Credit'}]})}</div></section>`;
  ['shipLinesGrid','shipSoGrid','shipInvTxnGrid','shipInvoicesGrid','shipFinancialGrid'].forEach(bindGrid);
  document.querySelectorAll('.erp-tabs .tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.erp-tabs .tab').forEach(x=>x.classList.remove('active')); b.classList.add('active'); document.querySelectorAll('#shipTab0,#shipTab1,#shipTab2,#shipTab3,#shipTab4').forEach((p,i)=>p.classList.toggle('hidden',String(i)!==b.dataset.tab));});
  $('#shipBack').onclick=()=>returnToValidatedOrigin('/sales-orders/shipments');
}
async function renderSoShipments(){ const rows=await api('/api/sales-orders/shipments'); $('#title').textContent='Shipments'; configureRecordNavigationList({contextKey:'SALES_SHIPMENTS',module:'Sales Orders',listUrl:'/sales-orders/shipments',gridId:'shipGrid',records:rows.map(row=>({id:row.shipmentNumber||row.id,type:'Shipment',detailUrl:`/sales-orders/shipments/${encodeURIComponent(row.shipmentNumber||row.id)}`}))}); $('#view').innerHTML=`<div class='header-row'><h3>Shipments</h3></div>${ErpDataGrid({id:'shipGrid',columns:[{key:'shipmentNumber',label:'Shipment Number',render:row=>`<a class='link' href='/sales-orders/shipments/${encodeURIComponent(row.shipmentNumber||row.id)}'>${esc(row.shipmentNumber||row.id)}</a>`},{key:'salesOrderNumber',label:'Sales Order Number',render:r=>`<a class='link' href='/sales-orders/orders/${r.salesOrderNumber}'>${r.salesOrderNumber}</a>`},{key:'customerName',label:'Customer'},{key:'shipDate',label:'Ship Date'},{key:'warehouse',label:'Warehouse'},{key:'shipVia',label:'Ship Via'},{key:'trackingNumber',label:'Tracking Number'},{key:'status',label:'Status'},{key:'freightAmount',label:'Freight Amount'}],rows})}`; bindGrid('shipGrid'); }
async function renderSoInvoices(){ const rows=await api('/api/sales-orders/invoices'); $('#title').textContent='Sales Order Invoices'; $('#view').innerHTML=`<div class='header-row'><h3>Sales Order Invoices</h3></div>${ErpDataGrid({id:'soInvGrid',columns:[{key:'invoiceNumber',label:'Invoice Number',render:r=>`<a class='link' href='/ar/doc/${r.invoiceId}'>${r.invoiceNumber}</a>`},{key:'invoiceDate',label:'Invoice Date'},{key:'salesOrderNumber',label:'Sales Order',render:r=>`<a class='link' href='/sales-orders/orders/${r.salesOrderNumber}'>${r.salesOrderNumber}</a>`},{key:'shipmentId',label:'Shipment Number'},{key:'invoiceAmount',label:'Invoice Amount'},{key:'openBalance',label:'Open Balance'},{key:'status',label:'Status'},{key:'arReference',label:'AR Reference'}],rows})}`; bindGrid('soInvGrid'); }
async function renderSoReports(kind){ const orders=await api('/api/sales-orders'); let rows=orders,title='Sales Order Inquiry'; if(kind.includes('backorder')){title='Backorders'; rows=orders.filter(o=>(o.lines||[]).some(l=>Number(l.qtyBackordered)>0));} if(kind.includes('pending-shipment')){title='Orders Pending Shipment'; rows=orders.filter(o=>(o.lines||[]).some(l=>Number(l.qtyOrdered)>Number(l.qtyShipped)));} if(kind.includes('pending-invoice')){title='Orders Pending Invoice'; rows=orders.filter(o=>(o.lines||[]).some(l=>Number(l.qtyShipped)>Number(l.qtyInvoiced)));} if(kind.includes('customer')) title='Sales by Customer'; if(kind.includes('item')) title='Sales by Item'; $('#title').textContent=title; $('#view').innerHTML=`${ErpDataGrid({id:'soReportGrid',columns:[{key:'orderNumber',label:'Order Number',render:r=>`<a class='link' href='/sales-orders/orders/${r.orderNumber}'>${r.orderNumber}</a>`},{key:'customerName',label:'Customer'},{key:'orderDate',label:'Order Date'},{key:'status',label:'Status'},{key:'orderTotal',label:'Order Total'},{key:'openBalance',label:'Open Amount'},{key:'warehouse',label:'Warehouse'}],rows})}`; bindGrid('soReportGrid'); }

const invDocTypeFromPath=(path)=>path.includes('receipt')?'Receipt':path.includes('issue')?'Issue':path.includes('transfer')?'Transfer':path.includes('physical')?'Physical Count':path.includes('adjustment')?'Adjustment':'Adjustment';
const invToolbar=()=>`<div class='erp-toolbar sticky'><button id='invBack'>Back</button><button id='invSaveClose'>Save & Close</button><button id='invSave'>Save</button><button id='invNew'>New</button><button id='invDelete'>Delete</button><button id='invPost'>Post</button><button id='invVoid'>Void</button><select id='invActions'><option>Actions</option><option>Validate Accounts</option><option>Copy Document</option></select><select id='invInq'><option>Inquiries</option><option>Item Availability</option><option>Transactions</option></select><select id='invReports'><option>Reports</option><option>Inventory Valuation</option><option>Inventory Movement</option></select><button>|&lt;</button><button>&lt;</button><button>&gt;</button><button>&gt;|</button></div>`;
async function renderInventoryRoute(v){ $('#title').textContent='Inventory'; const path=location.pathname; if(path==='/inventory') return renderInventoryOverview(v); if(path.startsWith('/inventory/documents/')) return renderInventoryDocumentDetail(v,decodeURIComponent(path.split('/').pop())); if(path==='/inventory/items') return renderInventoryItems(v); if(path.startsWith('/inventory/items/')) return renderInventoryItemDetail(v,path.split('/').pop()); if(['/inventory/receipts','/inventory/issues','/inventory/adjustments','/inventory/transfers','/inventory/physical-counts'].includes(path)) return renderInventoryDocuments(v,invDocTypeFromPath(path)); if(path==='/inventory/release') return renderInventoryRelease(v); if(path==='/inventory/summary'||path.includes('/reports/on-hand')) return renderInventorySummary(v); if(path==='/inventory/availability'||path.includes('/reports/availability')) return renderInventoryAvailability(v); if(path==='/inventory/valuation-inquiry'||path.includes('/reports/valuation')||path==='/inventory/valuation-process') return renderInventoryValuation(v); if(path.startsWith('/inventory/transactions/')) return renderInventoryTransactionDetail(v,path.split('/').pop()); if(path==='/inventory/transactions'||path.includes('/reports/movement')) return renderInventoryTransactions(v); if(path==='/inventory/warehouses') return renderSetupGrid(v,'Warehouses','/api/inventory/warehouses','whGrid'); if(path==='/inventory/locations') return renderSetupGrid(v,'Locations','/api/inventory/locations','locGrid'); if(path==='/inventory/item-classes'||path==='/inventory/uom'||path==='/inventory/reason-codes'||path==='/inventory/costing-methods') return renderInventorySetup(v,path); if(path==='/inventory/prepare-replenishment'||path==='/inventory/create-purchase-orders'||path==='/inventory/create-transfer-orders') return renderPrepareReplenishment(v); if(path.includes('/replenishment')||path.includes('/reports/reorder')) return renderReorderReport(v); v.innerHTML='<div class="panel">Inventory function is available from the navigation with live inventory data.</div>'; }
async function renderInventoryOverview(v){ const [sum,docs,items]=await Promise.all([api('/api/inventory/summary'),api('/api/inventory/documents'),api('/api/inventory/items')]); const total=sum.reduce((s,r)=>s+Number(r.inventoryValue||0),0); const low=sum.filter(r=>Number(r.qtyAvailable)<=Number(items.find(i=>i.code===r.inventoryId)?.reorderPoint||0)); const back=sum.filter(r=>Number(r.qtyBackordered)>0); const alloc=sum.filter(r=>Number(r.qtyAllocated)>0); v.innerHTML=`<div class='grid4'><section class='kpi panel'><h3>Total Inventory Value</h3><div class='big'>${fmtMoney(total)}</div><a class='link' href='/inventory/valuation-inquiry'>Drill to valuation</a></section><section class='kpi panel'><h3>Low Stock Items</h3><div class='big'>${low.length}</div><a class='link' href='/inventory/reports/reorder'>Reorder report</a></section><section class='kpi panel'><h3>Backordered Items</h3><div class='big'>${back.length}</div><a class='link' href='/inventory/availability'>Availability</a></section><section class='kpi panel'><h3>Items Allocated to SO</h3><div class='big'>${alloc.length}</div><a class='link' href='/inventory/summary'>Summary</a></section></div><div class='grid4'><section class='panel'><h3>Inventory Adjustments This Month</h3><div class='big'>${docs.filter(d=>d.documentType==='Adjustment').length}</div></section><section class='panel'><h3>Open Receipts</h3><div class='big'>${docs.filter(d=>d.documentType==='Receipt'&&d.status!=='Posted').length}</div></section><section class='panel'><h3>Open Issues</h3><div class='big'>${docs.filter(d=>d.documentType==='Issue'&&d.status!=='Posted').length}</div></section><section class='panel'><h3>Open Transfers</h3><div class='big'>${docs.filter(d=>d.documentType==='Transfer'&&d.status!=='Posted').length}</div></section></div>`; }
async function renderInventoryItems(v){ const rows=await api('/api/inventory/items'); configureRecordNavigationList({contextKey:'INVENTORY_ITEMS',module:'Inventory',listUrl:'/inventory/items',gridId:'invItemsGrid',records:rows.map(row=>({id:row.code||row.id,type:'Inventory Item',detailUrl:`/inventory/items/${encodeURIComponent(row.code||row.id)}`}))}); v.innerHTML=`<div class='header-row'><h3>Inventory Items</h3><button onclick="navigateTo('/inventory/items/new')">New Item</button></div>${ErpDataGrid({id:'invItemsGrid',columns:[{key:'code',label:'Inventory ID',render:r=>`<a class='link' href='/inventory/items/${r.code}'>${r.code}</a>`},{key:'description',label:'Description'},{key:'type',label:'Item Type'},{key:'status',label:'Status'},{key:'baseUom',label:'Base UOM'},{key:'defaultWarehouse',label:'Default Warehouse'},{key:'costingMethod',label:'Costing Method'},{key:'salesPrice',label:'Sales Price'},{key:'standardCost',label:'Standard Cost'},{key:'averageCost',label:'Average Cost'},{key:'qtyAvailable',label:'Qty Available'}],rows})}`; bindGrid('invItemsGrid'); }
async function renderInventoryItemDetail(v,id){ const isNew=id==='new'; const [setup,accounts]=await Promise.all([api('/api/inventory/setup'),api('/api/gl/accounts')]); const item=isNew?{code:'',description:'',type:'Stock Item',status:'Active',baseUom:'EA',salesUom:'EA',purchaseUom:'EA',defaultWarehouse:'MAIN',defaultLocation:'MAIN-A1',costingMethod:'Average Cost',standardCost:0,averageCost:0,lastCost:0,salesPrice:0,taxCategory:'TAXABLE',trackQuantity:true,lotSerialTracking:'None',inventoryAccount:'1507',cogsAccount:'5110',revenueAccount:'4008',purchaseAccrualAccount:'2020',adjustmentAccount:'5109',varianceAccount:'5109'}:await api('/api/inventory/items/'+id); const acctOpts=(sel)=>accounts.map(a=>`<option value='${a.code}' ${a.code===sel?'selected':''}>${a.code} - ${a.name}</option>`).join(''); const whOpts=setup.warehouses.map(w=>`<option value='${w.warehouseId}' ${w.warehouseId===item.defaultWarehouse?'selected':''}>${w.warehouseId} - ${w.name}</option>`).join(''); const locOpts=setup.locations.map(l=>`<option value='${l.locationId}' ${l.locationId===item.defaultLocation?'selected':''}>${l.locationId}</option>`).join(''); v.innerHTML=`${invToolbar()}<section class='erp-workspace'><div class='erp-header-grid so-header'><label class='required'>Inventory ID<input id='iiCode' value='${esc(item.code||'')}' ${isNew?'':'readonly'}></label><label class='required'>Description<input id='iiDesc' value='${esc(item.description||'')}'></label><label>Item Type<select id='iiType'>${['Stock Item','Non-Stock Item','Service Item','Freight Item'].map(x=>`<option ${x===item.type?'selected':''}>${x}</option>`).join('')}</select></label><label>Status<select id='iiStatus'>${['Active','Inactive','No Sales','No Purchases','Discontinued'].map(x=>`<option ${x===item.status?'selected':''}>${x}</option>`).join('')}</select></label><label>Item Class<input id='iiClass' value='${item.itemClass||''}'></label><label>Base UOM<input id='iiBase' value='${item.baseUom||item.uom||'EA'}'></label><label>Sales UOM<input id='iiSalesUom' value='${item.salesUom||'EA'}'></label><label>Purchase UOM<input id='iiPurchUom' value='${item.purchaseUom||'EA'}'></label><label>Default Warehouse<select id='iiWh'>${whOpts}</select></label><label>Default Location<select id='iiLoc'>${locOpts}</select></label><label>Costing Method<select id='iiCosting'>${['Standard Cost','Average Cost','FIFO'].map(x=>`<option ${x===item.costingMethod?'selected':''}>${x}</option>`).join('')}</select></label><label>Standard Cost<input id='iiStd' type='number' value='${item.standardCost||0}'></label><label>Average Cost<input id='iiAvg' type='number' value='${item.averageCost||0}' readonly></label><label>Last Cost<input id='iiLast' type='number' value='${item.lastCost||0}' readonly></label><label>Sales Price<input id='iiPrice' type='number' value='${item.salesPrice||0}'></label><label>Tax Category<input id='iiTax' value='${item.taxCategory||''}'></label><label>Track Quantity<select id='iiTrack'><option value='true' ${item.trackQuantity!==false?'selected':''}>true</option><option value='false' ${item.trackQuantity===false?'selected':''}>false</option></select></label><label>Lot/Serial Tracking<input id='iiLot' value='${item.lotSerialTracking||'None'}'></label></div><div class='tabs'><button>General</button><button>Sales</button><button>Purchase</button><button>Warehouse Details</button><button>GL Accounts</button><button>Pricing</button><button>Availability</button><button>Transactions</button><button>Replenishment</button><button>Vendors</button><button>Purchase Orders</button><button>Receipts</button><button>Sales Orders</button><button>Transactions</button><button>Attachments</button></div><div class='panel'><h3>GL Accounts</h3><div class='erp-header-grid'><label>Inventory Account<select id='iiInvAcct'>${acctOpts(item.inventoryAccount)}</select></label><label>COGS Account<select id='iiCogs'>${acctOpts(item.cogsAccount)}</select></label><label>Revenue Account<select id='iiRev'>${acctOpts(item.revenueAccount)}</select></label><label>Purchase Accrual / RNI<select id='iiRni'>${acctOpts(item.purchaseAccrualAccount||'2020')}</select></label><label>Inventory Adjustment<select id='iiAdj'>${acctOpts(item.adjustmentAccount||'5109')}</select></label><label>Scrap / Variance<select id='iiVar'>${acctOpts(item.varianceAccount||'5109')}</select></label></div></div><div class='panel'><h3>Replenishment</h3><div class='erp-header-grid'><label>Replenishment Method<select id='iiReplMethod'>${['None','Reorder Point','Min/Max','Demand Based','Manual'].map(x=>`<option ${x===(item.replenishmentMethod||'Reorder Point')?'selected':''}>${x}</option>`).join('')}</select></label><label>Replenishment Source<select id='iiReplSource'>${['Purchase','Transfer','Manufacturing','Drop Ship'].map(x=>`<option ${x===(item.replenishmentSource||'Purchase')?'selected':''}>${x}</option>`).join('')}</select></label><label>Preferred Vendor<input id='iiVendor' value='${item.preferredVendor||''}'></label><label>Reorder Point<input id='iiReorder' type='number' value='${item.reorderPoint||0}'></label><label>Min Qty<input id='iiMinQty' type='number' value='${item.minQty||0}'></label><label>Max Qty<input id='iiMaxQty' type='number' value='${item.maxQty||0}'></label><label>Safety Stock<input id='iiSafety' type='number' value='${item.safetyStock||0}'></label><label>Lead Time Days<input id='iiLead' type='number' value='${item.leadTimeDays||0}'></label><label>Minimum Order Qty<input id='iiMinOrder' type='number' value='${item.minimumOrderQty||0}'></label><label>Order Multiple<input id='iiOrderMult' type='number' value='${item.orderMultiple||1}'></label></div></div><div class='panel'><h3>Vendors</h3>${ErpDataGrid({id:'iiVendorGrid',columns:[{key:'vendorId',label:'Vendor ID'},{key:'vendorItemId',label:'Vendor Item ID'},{key:'price',label:'Price'},{key:'leadTimeDays',label:'Lead Time Days'}],rows:(item.vendorItems||[]).length?item.vendorItems:[]})}</div><div class='panel'><h3>Purchase Orders</h3>${ErpDataGrid({id:'iiPoGrid',columns:[{key:'poNumber',label:'PO Number',render:r=>`<a class='link' href='/purchase-orders/orders/${r.poNumber}'>${r.poNumber}</a>`},{key:'vendor',label:'Vendor',render:r=>r.vendorId?`<a class='link' href='/ap/vendors'>${esc(r.vendor)}</a>`:esc(r.vendor||'')},{key:'orderedQty',label:'Ordered Qty'},{key:'receivedQty',label:'Received Qty'},{key:'openQty',label:'Open Qty'},{key:'status',label:'Status'}],rows:item.purchaseOrders||[]})}</div><div class='panel'><h3>Receipts</h3>${ErpDataGrid({id:'iiReceiptGrid',columns:[{key:'receiptNumber',label:'Receipt Number',render:r=>`<a class='link' href='/purchase-orders/receipts/${r.receiptNumber}'>${r.receiptNumber}</a>`},{key:'poNumber',label:'PO Number'},{key:'vendor',label:'Vendor'},{key:'receiptDate',label:'Date'},{key:'receivedQty',label:'Received Qty'},{key:'unitCost',label:'Unit Cost'},{key:'status',label:'Status'}],rows:item.receipts||[]})}</div><div class='panel'><h3>Sales Orders</h3>${ErpDataGrid({id:'iiSoGrid',columns:[{key:'orderNumber',label:'Order Number'},{key:'customer',label:'Customer'},{key:'qtyOrdered',label:'Ordered Qty'},{key:'qtyShipped',label:'Shipped Qty'},{key:'qtyBackordered',label:'Backordered Qty'},{key:'status',label:'Status'}],rows:item.salesOrders||[]})}</div><div class='panel'><h3>Transactions</h3>${ErpDataGrid({id:'iiTxGrid',columns:[{key:'transactionId',label:'Transaction ID'},{key:'transactionType',label:'Type'},{key:'referenceNumber',label:'Reference'},{key:'postDate',label:'Date'},{key:'warehouse',label:'Warehouse'},{key:'quantityIn',label:'Qty In'},{key:'quantityOut',label:'Qty Out'},{key:'unitCost',label:'Unit Cost'}],rows:item.transactions||[]})}</div></section>`; $('#invBack').onclick=()=>navigateTo('/inventory/items'); $('#invNew').onclick=()=>navigateTo('/inventory/items/new'); $('#invSave').onclick=async()=>{const payload={code:$('#iiCode').value,description:$('#iiDesc').value,name:$('#iiDesc').value,type:$('#iiType').value,itemType:$('#iiType').value,status:$('#iiStatus').value,itemClass:$('#iiClass').value,baseUom:$('#iiBase').value,uom:$('#iiBase').value,salesUom:$('#iiSalesUom').value,purchaseUom:$('#iiPurchUom').value,defaultWarehouse:$('#iiWh').value,defaultLocation:$('#iiLoc').value,costingMethod:$('#iiCosting').value,standardCost:Number($('#iiStd').value||0),salesPrice:Number($('#iiPrice').value||0),taxCategory:$('#iiTax').value,trackQuantity:$('#iiTrack').value==='true',lotSerialTracking:$('#iiLot').value,inventoryAccount:$('#iiInvAcct').value,cogsAccount:$('#iiCogs').value,revenueAccount:$('#iiRev').value,purchaseAccrualAccount:$('#iiRni').value,adjustmentAccount:$('#iiAdj').value,varianceAccount:$('#iiVar').value,reorderPoint:Number($('#iiReorder').value||0),safetyStock:Number($('#iiSafety').value||0),preferredVendor:$('#iiVendor').value,leadTimeDays:Number($('#iiLead').value||0),replenishmentMethod:$('#iiReplMethod').value,replenishmentSource:$('#iiReplSource').value,minQty:Number($('#iiMinQty').value||0),maxQty:Number($('#iiMaxQty').value||0),minimumOrderQty:Number($('#iiMinOrder').value||0),orderMultiple:Number($('#iiOrderMult').value||1)}; const res=isNew?await api('/api/inventory/items',{method:'POST',body:JSON.stringify(payload)}):await api('/api/inventory/items/'+item.code,{method:'PUT',body:JSON.stringify(payload)}); navigateTo('/inventory/items/'+res.code);}; $('#invSaveClose').onclick=async()=>{const payload={code:$('#iiCode').value,description:$('#iiDesc').value,name:$('#iiDesc').value,type:$('#iiType').value,itemType:$('#iiType').value,status:$('#iiStatus').value};try{if(isNew)await api('/api/inventory/items',{method:'POST',body:JSON.stringify(payload)});else await api('/api/inventory/items/'+item.code,{method:'PUT',body:JSON.stringify(payload)});await saveAndReturnToOrigin({canonicalFallback:'/inventory/items'});}catch(error){showErpDialog({title:'Unable to save item',message:error.message,type:'error'});}}; $('#invPost').disabled=true; $('#invVoid').disabled=true; $('#invDelete').disabled=!isNew; }
async function renderInventoryDocuments(v,type){ const docs=(await api('/api/inventory/documents')).filter(d=>d.documentType===type); v.innerHTML=`<div class='header-row'><h3>${type}s</h3><button id='newInvDoc'>New ${type}</button></div>${ErpDataGrid({id:'invDocGrid',columns:[{key:'referenceNumber',label:'Reference'},{key:'status',label:'Status'},{key:'date',label:'Date'},{key:'postPeriod',label:'Post Period'},{key:'warehouse',label:'Warehouse'},{key:'description',label:'Description'}],rows:docs})}<div class='panel'>${invToolbar()}<p>Select a document in the release process to post or void. All document types share ERP toolbar actions.</p></div>`; bindGrid('invDocGrid'); $('#newInvDoc').onclick=async()=>{const d=await api('/api/inventory/documents',{method:'POST',body:JSON.stringify({documentType:type,description:`New ${type}`,lines:[]})}); alert('Saved '+d.referenceNumber); router();}; }
