function bindForm(type,doc){ const readOnly=['Open','Closed'].includes(doc?.status)||doc?.status==='Voided'; if(readOnly){document.querySelectorAll('#docForm input,#docForm select').forEach(el=>{if(el.id!=='void')el.disabled=true;});} if($('#amount')) $('#amount').oninput=calcTotals;
 const customerSelector=bindPartySelector({numberId:'#customerNumber',nameId:'#customerName',hiddenId:'#customerId',items:window.__customers||[],kind:'customer',onPick:()=>{if(type==='Payment')loadPaymentApps();}});
 preventFormEnter(document);
 let formProcessing=false; const saveDoc=async()=>{if(formProcessing)return; if(!customerSelector?.validate()){customerSelector&&$('#customerNumber').reportValidity();return;} const b={type,customerId:$('#customerId').value,date:$('#date').value,terms:$('#terms').value,amount:Number($('#amount').value),method:$('#method')?.value,checkNumber:$('#checkNumber')?.value,cashAccount:$('#cashAccount')?.value}; if(type==='Payment'&&b.amount<=0){showErpDialog({title:'Invalid payment',message:'Payment amount must be greater than $0.00.',type:'error'});return;} if(type==='Payment'){ b.applications=[...document.querySelectorAll('.apply-amt,.apply-so-amt')].map(x=>({invoiceId:x.dataset.kind==='invoice'?x.dataset.id:undefined,salesOrderId:x.dataset.kind==='salesOrder'?x.dataset.id:undefined,amount:Number(x.value||0),cashApplied:Number(x.value||0)})).filter(a=>a.amount>0); }
 formProcessing=true;const button=$('#saveDoc');if(button){button.disabled=true;button.textContent='Saving...';}try{const res=doc?await api(`/api/ar/documents/${doc.id}`,{method:'PUT',body:JSON.stringify(b)}):await api('/api/ar/documents',{method:'POST',body:JSON.stringify(b)});showErpDialog({title:'Saved',message:`${type} ${res.id} was saved successfully.`});history.pushState({},'',`/ar/doc/${res.id}`);router();}catch(error){showErpDialog({title:`Unable to save ${type}`,message:error.message,details:error.message,type:'error'});}finally{formProcessing=false;if(button?.isConnected){button.disabled=false;button.textContent='Save';}} }; if($('#saveDoc')) $('#saveDoc').onclick=saveDoc;
 $('#del').onclick=async()=>{ if(!doc) return history.pushState({},'','/ar/invoices'),router(); if(doc.status!=='Saved'){alert('Posted transactions cannot be deleted. Please void the transaction instead.'); return;} if(!confirm('Are you sure you want to delete this transaction? This action cannot be undone.')) return; await api(`/api/ar/documents/${doc.id}`,{method:'DELETE'}); alert('Deleted'); history.pushState({},'',`/ar/${doc.type==='Payment'?'payments':'invoices'}`); router(); };
 $('#post').onclick=async()=>{ if(formProcessing)return; if(!doc){alert('Save first'); return;} if(type==='Payment'&&Number(doc.amount)<=0){showErpDialog({title:'Invalid payment',message:'Payment amount must be greater than $0.00.',type:'error'});return;} if(!confirm('Are you sure you want to post this transaction? Once posted, it cannot be deleted.')) return; formProcessing=true;const button=$('#post');button.disabled=true;button.textContent='Posting...';try{await api('/api/ar/documents/post',{method:'POST',body:JSON.stringify({id:doc.id})});showErpDialog({title:'Posted',message:`${type} ${doc.id} was posted successfully.`});router();}catch(error){showErpDialog({title:`Unable to post ${type}`,message:error.message,details:error.message,type:'error'});}finally{formProcessing=false;if(button.isConnected){button.disabled=false;button.textContent='Post';}} };
 if($('#void')) $('#void').onclick=async()=>{ await api('/api/ar/documents/void',{method:'POST',body:JSON.stringify({id:doc.id})}); alert('Voided'); router(); };
}
$('#login-form').onsubmit=async(e)=>{e.preventDefault();try{await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('#username').value,password:$('#password').value})});csrfToken=(await api('/api/auth/csrf')).csrfToken||'';$('#password').value='';$('#login-screen').classList.add('hidden');$('#app').classList.remove('hidden');router();}catch(err){$('#password').value='';$('#login-error').textContent=err.message;}};
