  const [rows,dash,vendors]=await Promise.all([api('/api/ap/incoming-documents'),api('/api/ap/incoming-documents/dashboard'),api('/api/ap/vendors')]);
  
  const kpi=(label,value)=>`<div class='panel'><h4>${label}</h4><div class='big-number'>${value}</div></div>`;
  const grid=ErpDataGrid({id:'incomingDocsGrid',columns:[{key:'id',label:'Document ID',render:r=>`<a class='link incoming-select' href='/ap/incoming-documents/${encodeURIComponent(r.id)}/review'>${r.id}</a>`},{key:'originalFileName',label:'Filename',render:r=>`<a class='link incoming-select' href='/ap/incoming-documents/${encodeURIComponent(r.id)}/review'>${esc(r.originalFileName||r.fileName||'')}</a>`},{key:'uploadedAt',label:'Upload Date',render:r=>esc((r.uploadedAt||r.createdAt||'').slice(0,10))},{key:'source',label:'Source'},{key:'parentDocumentId',label:'Parent Document',render:r=>r.parentDocumentId?`<a class='link' href='/ap/incoming-documents/${encodeURIComponent(r.parentDocumentId)}/review'>${esc(r.parentDocumentId)}</a>`:''},{key:'sourcePageNumbers',label:'Source Pages',render:r=>esc((r.sourcePageNumbers||[]).join(', '))},{key:'splitStatus',label:'Split Status',render:r=>esc(r.splitStatus||'')},{key:'childDocumentIds',label:'Child Documents',render:r=>(r.childDocumentIds||[]).map(id=>`<a class='link' href='/ap/incoming-documents/${encodeURIComponent(id)}/review'>${esc(id)}</a>`).join(', ')},{key:'vendorMatch',label:'Vendor',render:r=>{const v=esc(r.vendorMatch?.vendorName||r.extracted?.vendorName||'');return v?`<a class='link incoming-select' href='/ap/incoming-documents/${encodeURIComponent(r.id)}/review'>${v}</a>`:'';}},{key:'invoiceNumber',label:'Vendor Invoice Number',render:r=>r.extracted?.invoiceNumber?`<a class='link incoming-select' href='/ap/incoming-documents/${encodeURIComponent(r.id)}/review'>${esc(r.extracted.invoiceNumber)}</a>`:''},{key:'poNumber',label:'PO Number',render:r=>{const po=r.extracted?.purchaseOrderNumber||r.extracted?.poNumber||'';return po?`<a class='link incoming-select' href='/ap/incoming-documents/${encodeURIComponent(r.id)}/review'>${esc(po)}</a>`:'';}},{key:'invoiceDate',label:'Invoice Date',render:r=>esc(r.extracted?.invoiceDate||'')},{key:'amount',label:'Invoice Total',render:r=>fmtMoney(r.extracted?.grossInvoiceAmount||r.extracted?.totalAmount||0)},{key:'currency',label:'Currency',render:r=>esc(r.extracted?.currency||'USD')},{key:'status',label:'Status',render:r=>recognitionStatusHtml(r)},{key:'actions',label:'Actions',render:r=>`<button class='incoming-select' data-id='${r.id}'>Review</button> <button class='incoming-delete' data-id='${r.id}'>Delete</button>`}],rows});
  const selected=rows.find(r=>r.id===selectedDocumentId)||null;
  const canProcess=!!(selected&&selected.storageKey&&!['PROCESSING','Processing','QUEUED','Queued'].includes(selected.processingStatus||selected.status));
